css:
body[data-theme="icalia"] { font-family: 'Inter', ui-sans-serif, system-ui, sans-serif; --icalia-navy: #1C2333; --icalia-red: #CC3239; }
/* Display: Inter Black (900) — heavy, tight tracking */
body[data-theme="icalia"] .display { font-family: 'Inter', ui-sans-serif, sans-serif; font-weight: 900; letter-spacing: -0.03em; }
/* Eyebrow labels: Trebuchet MS spaced caps (Icalia brand spec) */
body[data-theme="icalia"] .uppercase.tracking-\[0\.2em\],
body[data-theme="icalia"] .uppercase.tracking-wider,
body[data-theme="icalia"] .eyebrow { font-family: 'Trebuchet MS', Arial, sans-serif; letter-spacing: 0.16em; font-weight: 700; }
body[data-theme="icalia"] .num-marker { font-variant-numeric: tabular-nums; }
/* Fixed 4px left red accent bar — continuous brand signal */
body[data-theme="icalia"]::before { content: ''; position: fixed; left: 0; top: 0; bottom: 0; width: 4px; background: #CC3239; z-index: 200; pointer-events: none; }
@media print { body[data-theme="icalia"]::before { display: none; } }
/* Inset surfaces use Icalia navy (cover, next-step, dark banners) */
body[data-theme="icalia"] .bg-slate-900,
body[data-theme="icalia"] .bg-icalia-navy { background: #1C2333 !important; }
/* Slate scale stays slate but pulled slightly cooler — keeps WCAG safe */
body[data-theme="icalia"] .text-slate-900 { color: #0F172A !important; }
body[data-theme="icalia"] .text-slate-700 { color: #334155 !important; }
body[data-theme="icalia"] .text-slate-600 { color: #475569 !important; }
body[data-theme="icalia"] .text-slate-500 { color: #64748B !important; }
/* slate-400 on white fails WCAG (2.6:1) — bump to slate-500 */
body[data-theme="icalia"] .text-slate-400 { color: #64748B !important; }
/* Hyperlinks adopt the brand red */
body[data-theme="icalia"] a:not(.no-brand) { color: #CC3239; }
body[data-theme="icalia"] a:not(.no-brand):hover { color: #A82A30; }
